INSERT INTO `ai_chat_message` VALUES (20, 7, 'assistant', '好的！请问您对手机有什么具体需求吗？比如：  \n- **预算**：比如2000元以内、3000-4000元等。  \n- **用途**：日常使用、游戏、拍照、商务等。  \n- **品牌偏好**：是否有喜欢的品牌（如华为、小米、苹果等）？  \n\n根据您的需求，我可以为您精准推荐合适的手机型号！📱😊', NULL, NULL, '2026-03-03 10:27:58', NULL);
INSERT INTO `ai_chat_message` VALUES (21, 7, 'user', '我系统里面有什么手机商品', NULL, NULL, '2026-03-03 10:29:09', NULL);
INSERT INTO `ai_chat_message` VALUES (22, 7, 'assistant', '好的！根据您的需求，我可以为您推荐几款不同价位和用途的热门手机 📱，供您参考：\n\n### 1. **预算2000元以内**\n   - **Redmi Note 12 Turbo**  \n     - **核心卖点**：骁龙7+ Gen2处理器，性能强劲；120Hz OLED屏幕；5000mAh大电池。  \n     - **价格**：约1799元起。  \n     - **适合人群**：学生党或预算有限，注重性价比的用户。  \n\n### 2. **预算3000-4000元**\n   - **realme GT5**  \n     - **核心卖点**：骁龙8 Gen2旗舰芯片；144Hz高刷屏；240W快充，充电速度极快。  \n     - **价格**：约3299元起。  \n     - **适合人群**：游戏玩家或追求高性能的用户。  \n\n### 3. **拍照旗舰**\n   - **vivo X90**  \n     - **核心卖点**：蔡司镜头+自研V2芯片，拍照效果顶级；天玑9200芯片；120Hz曲面屏。  \n     - **价格**：约3999元起。  \n     - **适合人群**：摄影爱好者或注重影像体验的用户。  \n\n### 4. **高端商务**\n   - **华为Mate 60 Pro**  \n     - **核心卖点**：鸿蒙OS 4.0；昆仑玻璃+卫星通信；XMAGE影像系统。  \n     - **价格**：约6999元起。  \n     - **适合人群**：商务人士或华为生态用户。  \n\n如果您有更具体的需求（比如品牌偏好或特殊功能），可以告诉我，我会进一步为您筛选！  \n或者，您是否需要了解某款手机的更多详情？😊', NULL, NULL, '2026-03-03 10:29:25', NULL);
INSERT INTO `ai_chat_message` VALUES (23, 7, 'user', '你们系统有什么商品卖', NULL, NULL, '2026-03-03 11:56:41', NULL);
