INSERT INTO `ai_chat_message` VALUES (34, 10, 'assistant', '您好！我们系统中有丰富的商品，包括电子产品、家居用品、服饰鞋包、图书音像、食品饮料等。您需要了解哪一类商品呢？或者可以告诉我您想购买的场景和预算，我可以为您推荐合适的产品 😊', NULL, NULL, '2026-03-03 21:33:39', NULL);
INSERT INTO `ai_chat_message` VALUES (35, 11, 'user', '你们有什么商品卖', NULL, NULL, '2026-03-03 22:03:12', NULL);
INSERT INTO `ai_chat_message` VALUES (36, 11, 'assistant', '您好！我是小智，您的电商智能客服助手 😊\n\n我可以为您提供以下服务：\n\n🛍️ **商品导购**\n- 搜索商品、查看商品详情\n- 对比商品参数\n- 根据场景和预算为您推荐商品\n\n📦 **订单服务**\n- 查询您的订单状态\n- 查看物流进度\n\n🔧 **售后支持**\n- 提交投诉、退款、换货、咨询工单\n- 查询工单处理进度\n\n请问有什么可以帮您的吗？您可以直接告诉我您的需求，比如：\n- \"我想买一台笔记本电脑，预算5000元左右\"\n- \"帮我查一下订单ORD20250001的物流\"\n- \"我想对比两款手机\"\n- \"我的商品有问题，需要申请退款\"\n\n随时为您服务！👍', NULL, NULL, '2026-03-03 22:03:18', NULL);
INSERT INTO `ai_chat_message` VALUES (37, 12, 'user', '你们有什么商品卖', NULL, NULL, '2026-03-03 22:22:28', NULL);
INSERT INTO `ai_chat_message` VALUES (38, 12, 'assistant', '您好！😊 我们商城目前有丰富的商品供您选择，主要分为以下几类：\n\n## 📱 手机系列\n- **iPhone 15 Pro Max 256GB** - ¥12,990（库存96件）\n- **华为 Mate 60 Pro** - ¥6,999（库存80件）\n- **小米14 Ultra** - ¥5,999（库存120件）\n\n## 💻 电脑系列\n- **MacBook Pro 14英寸 M3** - ¥12,999（库存50件）\n- **联想 ThinkPad X1 Carbon** - ¥8,999（库存60件）\n\n## 🎧 配件系列\n- **AirPods Pro 2** - ¥1,799（库存200件）\n- **华为 FreeBuds Pro 3** - ¥1,199（库存150件）\n- **Apple Watch Series 9** - ¥2,999（库存80件）\n\n## 📟 平板系列\n- **iPad Air M2** - ¥4,799（库存70件）\n- **华为 MatePad Pro 13.2** - ¥5,699（库存40件）\n\n---\n\n请问您对哪类商品感兴趣呢？我可以为您提供：\n- 🔍 **商品详情**：查看具体规格参数\n- ⚖️ **商品对比**：帮您对比两款商品的差异\n- 💡 **场景推荐**：根据您的使用场景和预算推荐合适的商品\n\n是否需要了解更多详情呢？😊', NULL, NULL, '2026-03-03 22:22:41', NULL);
INSERT INTO `ai_chat_message` VALUES (39, 12, 'user', '查看我的订单', NULL, NULL, '2026-03-03 22:27:30', NULL);
INSERT INTO `ai_chat_message` VALUES (40, 12, 'assistant', '您好！😊 我为您查询到当前共有 **2个订单**：\n\n## 📋 您的订单列表\n\n| 订单编号 | 订单金额 | 下单时间 | 状态 |\n|---------|---------|---------|------|\n| ORD2027960831975133184 | ¥38,970.00 | 2026-03-01 12:15 | ✅ 已付款 |\n| ORD2027692769887748096 | ¥9,999.00 | 2026-02-28 18:30 | ✅ 已付款 |\n\n---\n\n两个订单目前都是**已付款**状态，请问您需要：\n\n1. 📦 **查看订单详情**：了解具体购买了哪些商品\n2. 🚚 **查询物流进度**：查看商品配送情况\n3. ❓ **其他问题**：如有任何疑问随时告诉我\n\n您可以告诉我订单编号，我帮您查询更详细的信息哦！😊', NULL, NULL, '2026-03-03 22:27:39', NULL);
INSERT INTO `ai_chat_message` VALUES (41, 12, 'user', '我刚刚问你什么了', NULL, NULL, '2026-03-03 23:00:32', NULL);
INSERT INTO `ai_chat_message` VALUES (42, 12, 'assistant', '您好！😊 回顾一下我们之前的对话，您刚刚问了两个问题：\n\n1. **第一问**：\"你们有什么商品卖\" \n   - 我为您介绍了商城的商品分类和主要商品\n\n2. **第二问**：\"查看我的订单\"\n   - 我为您查询到共有 2 个订单，都是已付款状态\n\n---\n\n现在您是想继续了解商品信息，还是需要查询某个订单的详情呢？📦\n\n有任何需要随时告诉我哦！😊', NULL, NULL, '2026-03-03 23:00:39', NULL);
INSERT INTO `ai_chat_message` VALUES (43, 12, 'user', '为我推荐一个华为手机', NULL, NULL, '2026-03-04 11:26:54', NULL);
INSERT INTO `ai_chat_message` VALUES (44, 12, 'assistant', '您好！😊 根据您的需求，我为您推荐一款华为手机：\n\n## 📱 华为 Mate 60 Pro\n\n- **价格**：¥6,999.00\n- **库存**：80件（现货充足）\n- **分类**：手机\n\n---\n\n这款华为 Mate 60 Pro 是华为的旗舰机型，性能强劲，适合日常使用和商务办公。\n\n**是否需要了解更多详情呢？** 我可以为您：\n- 🔍 查看详细的规格参数和核心卖点\n- ⚖️ 与其他华为手机进行对比\n- 🛒 如果您感兴趣，可以直接加入购物车\n\n请问您想了解哪方面信息呢？😊', NULL, NULL, '2026-03-04 11:27:03', NULL);
INSERT INTO `ai_chat_message` VALUES (45, 13, 'user', '你好', NULL, NULL, '2026-03-04 13:27:12', NULL);
INSERT INTO `ai_chat_message` VALUES (46, 13, 'assistant', '您好！我是小智，您的电商智能客服助手 😊\n\n很高兴为您服务！我可以帮您：\n- 🛒 **商品导购**：搜索商品、查看详情、对比参数、根据需求推荐\n- 📦 **订单服务**：查询订单状态、物流信息、取消订单、确认收货\n- 🎧 **售后支持**：提交工单、查询进度、转接人工客服\n\n请问今天有什么可以帮您的吗？', NULL, NULL, '2026-03-04 13:27:17', NULL);
INSERT INTO `ai_chat_message` VALUES (47, 14, 'user', '你好', NULL, NULL, '2026-03-04 13:28:01', NULL);
INSERT INTO `ai_chat_message` VALUES (48, 14, 'assistant', '您好！我是小智，您的电商智能客服助手 😊\n\n很高兴为您服务！我可以帮您：\n\n🛍️ **商品导购** - 搜索商品、查看详情、对比参数、根据需求推荐\n📦 **订单服务** - 查询订单状态、物流信息、取消订单、确认收货\n🔧 **售后支持** - 提交工单、查询处理进度、转接人工客服\n\n请问今天有什么可以帮您的吗？比如想看看有什么商品，或者查询一下订单？', NULL, NULL, '2026-03-04 13:28:07', NULL);
INSERT INTO `ai_chat_message` VALUES (49, 14, 'user', '退货政策是什么', NULL, NULL, '2026-03-04 13:28:49', NULL);
INSERT INTO `ai_chat_message` VALUES (50, 14, 'assistant', '您好！关于退货政策，我来为您介绍一下 📋\n\n## 🔄 退货政策概览\n\n**1. 退货期限**\n- 支持 **7天无理由退货**（自签收之日起计算）\n- 部分特殊商品（如定制类、生鲜类）除外\n\n**2. 退货条件**\n- ✅ 商品完好，不影响二次销售\n- ✅ 原包装、配件、标签齐全\n- ✅ 未使用、未洗涤、无损坏\n\n**3. 退货流程**\n1. 在订单页面申请退货/提交售后工单\n2. 等待客服审核通过\n3. 按指定地址寄回商品\n4. 仓库收货验货后退款\n\n**4. 运费说明**\n- 📦 质量问题：平台承担往返运费\n- 📦 无理由退货：买家承担寄回运费\n\n**5. 退款时效**\n- 仓库验货确认后，**3-7个工作日** 原路退回\n\n---\n\n⚠️ **温馨提示**：如果您有具体订单需要退货，我可以帮您提交售后工单。请问您是需要了解某个订单的退货事宜吗？或者有其他问题需要咨询？😊', NULL, NULL, '2026-03-04 13:28:56', NULL);
INSERT INTO `ai_chat_message` VALUES (51, 14, 'user', '查看我的订单', NULL, NULL, '2026-03-04 13:30:40', NULL);
INSERT INTO `ai_chat_message` VALUES (52, 14, 'assistant', '您好！我为您查询到了以下订单信息 📦\n\n## 您的订单列表\n\n### 订单 1\n- **订单编号**：ORD2027960831975133184\n- **订单金额**：¥38,970.00\n- **下单时间**：2026-03-01 12:15\n- **订单状态**：✅ 已付款\n\n### 订单 2\n- **订单编号**：ORD2027692769887748096\n- **订单金额**：¥9,999.00\n- **下单时间**：2026-02-28 18:30\n- **订单状态**：✅ 已付款\n\n---\n\n💡 **温馨提示**：\n您的两个订单都已付款，接下来会进入发货流程。您可以：\n- 🔍 查询某个订单的详细信息（商品列表、物流等）\n- 📦 查看物流进度（发货后可查询）\n\n请问您想了解哪个订单的详细信息吗？或者需要查询物流信息？😊', NULL, NULL, '2026-03-04 13:30:48', NULL);
