INSERT INTO `ai_chat_message` VALUES (65, 17, 'user', '退货流程是什么', NULL, NULL, '2026-03-06 09:46:52', NULL);
INSERT INTO `ai_chat_message` VALUES (66, 17, 'assistant', '您好！我是小智，很高兴为您解答退货流程 😊\n\n## 📋 退货流程说明\n\n**1. 提交退货申请**\n- 在订单详情页点击\"申请售后\"\n- 或联系我帮您创建退款工单\n\n**2. 选择退货原因**\n- 商品质量问题\n- 七天无理由退货\n- 商品与描述不符\n- 其他原因\n\n**3. 等待审核**\n- 客服会在 1-2 个工作日内审核您的申请\n\n**4. 寄回商品**\n- 审核通过后，系统会提供退货地址\n- 请将商品原包装寄回（保持商品完好）\n\n**5. 退款处理**\n- 收到退货并验收合格后\n- 退款将在 3-5 个工作日内原路返回\n\n---\n\n## ⚠️ 注意事项\n- 退货商品需保持完好，不影响二次销售\n- 部分特殊商品（如定制类、生鲜类）不支持无理由退货\n- 请保留好物流单号，方便查询退货进度\n\n---\n\n**如果您需要办理退货**，请告诉我您的订单编号，我可以帮您直接提交退款工单 🛒\n\n请问有什么可以帮您的吗？😊', NULL, NULL, '2026-03-06 09:47:03', NULL);
INSERT INTO `ai_chat_message` VALUES (67, 18, 'user', '1', NULL, NULL, '2026-03-06 10:29:57', NULL);
INSERT INTO `ai_chat_message` VALUES (68, 18, 'assistant', '您好！我是小智，您的电商智能客服助手 😊\n\n我看到您发送了\"1\"，请问有什么可以帮助您的吗？我可以为您提供以下服务：\n\n🛍️ **商品导购** - 搜索商品、查看商品详情、对比商品参数、根据场景推荐商品\n📦 **订单服务** - 查询订单状态和物流信息、取消订单、确认收货\n🔧 **售后支持** - 提交售后工单、查询处理进度、转接人工客服\n\n请告诉我您需要什么帮助吧！', NULL, NULL, '2026-03-06 10:30:03', NULL);
INSERT INTO `ai_chat_message` VALUES (69, 18, 'user', '2', NULL, NULL, '2026-03-06 10:30:14', NULL);
