INSERT INTO `ai_chat_message` VALUES (90, 21, 'assistant', '您好呀！😊 \n\n很抱歉，我作为电商客服助手，无法查询实时天气信息呢～ 建议您查看手机天气 APP 或搜索\"天气\"来获取准确的天气预报哦！☀️🌧️\n\n不过，我可以帮您处理电商相关的事情，比如：\n- 🔍 搜索或推荐商品\n- 📦 查询订单状态和物流\n- 🛒 查看商品详情或对比参数\n- 📝 提交售后工单\n\n有什么我可以帮您的吗？😊', NULL, NULL, '2026-03-06 13:58:27', NULL);
INSERT INTO `ai_chat_message` VALUES (91, 23, 'user', '有什么热门商品推荐？', NULL, NULL, '2026-03-06 20:07:05', NULL);
INSERT INTO `ai_chat_message` VALUES (92, 23, 'assistant', '您好！我是小智，很高兴为您推荐热门商品！😊\n\n根据您的需求，我为您精选了以下几款热门商品：\n\n## 📱 手机类\n1. **iPhone 15 Pro Max 256GB** - ¥12,990\n   - 核心卖点：这里是核心买点\n   - 库存充足（95件）\n\n2. **华为 Mate 60 Pro** - ¥6,999\n   - 库存：80件\n\n3. **小米14 Ultra** - ¥5,999\n   - 库存：119件\n\n## 💻 电脑类\n4. **MacBook Pro 14英寸 M3** - ¥12,999\n   - 库存：50件\n\n5. **联想 ThinkPad X1 Carbon** - ¥8,999\n   - 库存：60件\n\n---\n\n这些商品都是当前热销的数码产品哦！🔥\n\n**请问您对哪款商品感兴趣呢？** \n- 想了解某款商品的详细参数和规格？\n- 需要我帮您对比两款商品？\n- 或者有特定的使用场景和预算，我可以为您做更精准的推荐？\n\n您可以直接告诉我商品名称，我帮您查看更多详情！🛒', NULL, NULL, '2026-03-06 20:07:18', NULL);
