INSERT INTO `ai_chat_message` VALUES (108, 23, 'assistant', '您好！我是小智，很高兴为您服务！😊\n\n## 📍 您的收货地址列表\n\n| ID | 联系人 | 手机号 | 收货地址 | 状态 |\n|----|--------|--------|----------|------|\n| 4 | 123 | 156****7896 | 天津市和平区 12311 | ⭐ **默认地址** |\n| 6 | 123 | 123 | 12311w*** | |\n| 5 | 123 | 123 | 12311w*** | |\n| 3 | 123 | 123 | 123 | |\n| 2 | sun | 111****1111 | 贵州省贵阳市*** | |\n| 1 | sun | 111****1111 | 贵州省贵阳市*** | |\n\n---\n\n### 📊 地址统计\n- **总地址数**：6个\n- **默认地址**：1个（天津市和平区）\n\n---\n\n**请问您需要：**\n- 🔄 **更改默认地址**？（告诉我地址ID，我帮您设置）\n- ➕ **添加新地址**？（需前往个人中心操作）\n- 📦 **下单时使用哪个地址**？\n- 💬 其他需要帮助的地方？\n\n随时告诉我哦！😊', NULL, NULL, '2026-03-08 22:02:04', NULL);
