INSERT INTO `ai_chat_message` VALUES (110, 23, 'assistant', '您好！我是小智，很高兴为您服务！😊\n\n## 📬 您的消息通知\n\n**当前没有未读通知哦！** ✅\n\n所有消息都已处理完毕，您可以放心啦~\n\n---\n\n**温馨提示：**\n- 如有新订单状态更新、物流信息或促销活动，系统会及时通知您\n- 您可以随时问我\"有新消息吗\"来查看最新通知\n\n**请问您还需要：**\n- 📦 查看您的订单列表？\n- 🛒 搜索或推荐商品？\n- 💬 其他需要帮助的地方？\n\n随时告诉我哦！😊', NULL, NULL, '2026-03-08 22:02:41', NULL);
INSERT INTO `ai_chat_message` VALUES (111, 23, 'user', '帮我评价这个商品', NULL, NULL, '2026-03-08 22:03:50', NULL);
INSERT INTO `ai_chat_message` VALUES (112, 23, 'assistant', '您好！我是小智，很高兴帮您进行商品评价！📝\n\n不过我需要确认一下具体信息：\n\n## ❓ 需要确认的信息\n\n1. **要评价哪个商品？**\n   根据您之前的订单 ORD2029731846887632896，包含以下商品：\n   - iPhone 15 Pro Max 256GB\n   - 华为 MatePad Pro 13.2\n   - 小米14 Ultra\n   \n   请问您想评价哪一款？\n\n2. **评分是多少？**（1-5分，5分为最高）\n   您之前提到过1星、2星，请确认具体评分\n\n3. **评价内容是什么？**\n   请告诉我您想写的评价内容\n\n---\n\n## 💡 评价流程说明\n\n确认以上信息后，我会帮您：\n1. ✅ 检查该商品是否已评价过\n2. 📝 提交您的评价\n\n**请告诉我：**\n- 商品名称\n- 评分（1-5分）\n- 评价内容\n\n随时告诉我哦！😊', NULL, NULL, '2026-03-08 22:04:01', NULL);
INSERT INTO `ai_chat_message` VALUES (113, 23, 'user', '我还有什么商品没有评价', NULL, NULL, '2026-03-08 22:14:52', NULL);
INSERT INTO `ai_chat_message` VALUES (114, 23, 'assistant', '您好！我是小智，我来帮您查看哪些商品还没有评价！📝\n\n## 📊 您的订单评价情况\n\n### ✅ 可以评价的订单（已送达状态）\n\n**订单 ORD2029731846887632896** - 状态：已送达\n| 商品名称 | 数量 |\n|---------|------|\n| iPhone 15 Pro Max 256GB | 1 |\n| 华为 MatePad Pro 13.2 | 1 |\n| 小米14 Ultra | 1 |\n\n---\n\n### ⏳ 暂不能评价的订单\n\n| 订单编号 | 状态 | 原因 |\n|---------|------|------|\n| ORD2030645615457333248 | 待付款 | 未付款，无法评价 |\n| ORD2030166584999833600 | 已退款 | 退款订单无法评价 |\n| ORD2027960831975133184 | 已付款 | 等待发货中 |\n| ORD2027692769887748096 | 已付款 | 等待发货中 |\n\n---\n\n## 📝 总结\n\n您目前有 **3件商品** 可以评价（来自已送达订单 ORD2029731846887632896）：\n1. iPhone 15 Pro Max 256GB\n2. 华为 MatePad Pro 13.2\n3. 小米14 Ultra\n\n**温馨提示：**\n- 只有\"已送达\"状态的订单才能进行评价\n- 其他订单需等待发货并送达后才能评价\n\n**请问您想：**\n- 📝 对以上商品进行评价？（请告诉我具体商品、评分和评价内容）\n- 📦 查询其他订单的物流进度？\n- 💬 有其他问题需要帮助？\n\n随时告诉我哦！😊', NULL, NULL, '2026-03-08 22:15:22', NULL);
INSERT INTO `ai_chat_message` VALUES (115, 25, 'user', '我买过什么商品了', NULL, NULL, '2026-03-08 23:43:39', NULL);
