INSERT INTO `ai_chat_message` VALUES (204, 36, 'user', '你好鸭', NULL, NULL, '2026-03-13 22:49:42', NULL);
INSERT INTO `ai_chat_message` VALUES (205, 36, 'assistant', '你好呀！👋 我是小智，您的数码商城智能客服助手～\n\n很高兴为您服务！😊 我可以帮您：\n- 📱 推荐和查询手机、电脑、耳机等数码产品\n- 🛒 管理购物车和订单\n- 📦 查询物流和售后\n- 💬 处理各种购物问题\n\n有什么我可以帮您的吗？比如想找某类产品、查询订单，或者有其他购物问题？随时告诉我哦～ 😊', NULL, NULL, '2026-03-13 22:49:48', NULL);
INSERT INTO `ai_chat_message` VALUES (206, 36, 'user', '你可以为我讲故事吗', NULL, NULL, '2026-03-13 22:50:14', NULL);
INSERT INTO `ai_chat_message` VALUES (207, 36, 'assistant', '您好呀！😊 我是小智，数码商城的智能客服助手～\n\n我的主要专长是帮您处理数码购物相关的事情，比如：\n- 📱 推荐和查询手机、电脑、耳机等数码产品\n- 🛒 管理购物车和订单\n- 📦 查询物流和售后问题\n- 💬 解答各类购物疑问\n\n讲故事暂时不是我的强项呢～不过如果您想选购数码产品、查询订单状态，或者有任何购物问题，我都很乐意帮您！😄\n\n今天有什么可以帮您的吗？比如想找某类产品，或者查询订单？🛒', NULL, NULL, '2026-03-13 22:50:21', NULL);
INSERT INTO `ai_chat_message` VALUES (208, 24, 'user', '有什么热门商品推荐？', NULL, NULL, '2026-03-13 22:59:50', NULL);
INSERT INTO `ai_chat_message` VALUES (209, 24, 'assistant', '为您精选了各品类的热门商品，看看有没有您感兴趣的吧！😊\n\n## 📱 热门手机\n1. **苹果 iPhone 16 Pro Max 256GB** - ¥8,999 | A18 Pro芯片，4800万像素三摄，钛金属边框\n2. **华为 Mate 70 Pro 12+256GB** - ¥6,499 | 麒麟9020芯片，5700mAh大电池，鸿蒙5.0系统\n3. **小米15 Pro 12+256GB** - ¥4,599 | 骁龙8至尊版，6100mAh超大电池，徕卡影像\n4. **三星 Galaxy S25 Ultra 12+256GB** - ¥8,999 | 2亿像素四摄，内置S Pen，Galaxy AI助手\n5. **OPPO Find X8 Pro 16+256GB** - ¥5,299 | 天玑9400芯片，哈苏影像，5910mAh电池\n\n## 💻 热门笔记本电脑\n1. **MacBook Air 13英寸 M4 16+256GB** - ¥7,999 | M4芯片，18小时续航，仅1.24kg轻薄\n2. **华为 MateBook X Pro 酷睿Ultra 7 16+1TB** - ¥11,199 | 仅980g超轻，14.2英寸OLED屏\n3. **联想 ThinkPad X1 Carbon 2025 Ultra7 32+1TB** - ¥12,999 | 商务旗舰，2.8K OLED屏，军标认证\n\n## 🎧 热门耳机\n1. **Apple AirPods Pro 3** - ¥1,899 | 2倍降噪性能，心率监测，触控充电盒\n2. **索尼 WH-1000XM6 头戴式** - ¥3,499 | QN3处理器，12麦克风阵列，LDAC高解析\n3. **华为 FreeBuds 6i** - ¥349 | 27dB智慧降噪，35小时续航，性价比之选\n4. **小米 Buds 5 Pro WiFi版** - ¥1,099 | 55dB超深度降噪，WiFi低延迟，空间音频\n5. **西圣 H1 Pro 头戴式** - ¥229 | 60小时续航，蓝牙6.0，百元价位降噪\n\n您对哪款产品感兴趣呢？我可以帮您查看详细信息、对比参数，或者直接加入购物车哦！🛒', NULL, '[{\"cardType\":\"product\",\"items\":[{\"productId\":12,\"name\":\"苹果 iPhone 16 Pro Max 256GB\",\"category\":\"手机\",\"price\":8999.00,\"stock\":48,\"imageUrl\":\"/profile/upload/2026/03/11/苹果 iPhone 16 Pro Max 256GB_20260311170748A002.png\",\"highlights\":\"A18 Pro芯片 性能强劲\\n钛金属边框 坚固轻盈\\n4800万像素融合式摄像头系统\\n支持Apple智能AI功能\\nUSB-C接口 传输速度更快\"},{\"productId\":13,\"name\":\"华为 Mate 70 Pro 12+256GB\",\"category\":\"手机\",\"price\":6499.00,\"stock\":31,\"imageUrl\":\"/profile/upload/2026/03/11/华为 Mate 70 Pro 12+256GB_20260311170758A003.png\",\"highlights\":\"麒麟9020旗舰芯片\\n鸿蒙5.0原生系统\\n5700mAh大电池 100W快充\\n3D人脸识别\\nIP69K防尘防水\"},{\"productId\":14,\"name\":\"小米15 Pro 12+256GB\",\"category\":\"手机\",\"price\":4599.00,\"stock\":59,\"imageUrl\":\"/profile/upload/2026/03/11/小米15 Pro 12+256GB_20260311170809A004.png\",\"highlights\":\"骁龙8至尊版旗舰性能\\n6100mAh超大电池\\n全焦段5000万三摄系统\\n2K超清护眼屏\\n金属中框 质感出色\"},{\"productId\":15,\"name\":\"三星 Galaxy S25 Ultra 12+256GB\",\"category\":\"手机\",\"price\":8999.00,\"stock\":24,\"imageUrl\":\"/profile/upload/2026/03/11/三星 Galaxy S25 Ultra 12+256GB_20260311170820A005.png\",\"highlights\":\"2亿像素四摄影像系统\\n骁龙8至尊版Galaxy定制芯片\\n内置S Pen书写体验\\nGalaxy AI智能助手\\n钛金属边框\"},{\"productId\":16,\"name\":\"OPPO Find X8 Pro 16+256GB\",\"category\":\"手机\",\"price\":5299.00,\"stock\":40,\"imageUrl\":\"/profile/upload/2026/03/11/OPPO Find X8 Pro 16+256GB_20260311171459A006.png\",\"highlights\":\"天玑9400旗舰芯片\\n哈苏影像四摄系统\\n5910mAh大电池全天候续航\\nColorOS 15 AI体验\\nIP69级防水\"}]},{\"cardType\":\"product\",\"items\":[{\"productId\":17,\"name\":\"MacBook Air 13英寸 M4 16+256GB\",\"category\":\"笔记本电脑\",\"price\":7999.00,\"stock\":30,\"imageUrl\":\"/profile/upload/2026/03/11/MacBook Air 13英寸 M4 16+256GB_20260311171519A007.png\",\"highlights\":\"M4芯片 性能全面提升\\n18小时超长续航\\n仅1.24kg极致轻薄\\n12MP Center Stage摄像头\\n天蓝色等4色可选\"},{\"productId\":18,\"name\":\"华为 MateBook X Pro 酷睿Ultra 7 16+1TB\",\"category\":\"笔记本电脑\",\"price\":11199.00,\"stock\":15,\"imageUrl\":\"/profile/upload/2026/03/11/华为 MateBook X Pro 酷睿Ultra 7 16+1TB_20260311171605A008.png\",\"highlights\":\"全球最轻14英寸性能本 仅980g\\n14.2英寸OLED原色全面屏\\n酷睿Ultra 7处理器\\n15小时超长续航\\n微绒金属机身 高级质感\"},{\"productId\":19,\"name\":\"联想 ThinkPad X1 Carbon 2025 Ultra7 32+1TB\",\"category\":\"笔记本电脑\",\"price\":12999.00,\"stock\":20,\"imageUrl\":\"/profile/upload/2026/03/11/联想 ThinkPad X1 Carbon 2025 Ultra7 32+1TB_20260311164333A001.png\",\"highlights\":\"经典ThinkPad商务旗舰\\n120 TOPS AI算力\\n2.8K OLED高色域屏\\n32GB大内存 专业办公\\nMIL-STD-810H军标认证\"}]},{\"cardType\":\"product\",\"items\":[{\"productId\":26,\"name\":\"Apple AirPods Pro 3\",\"category\":\"耳机\",\"price\":1899.00,\"stock\":55,\"imageUrl\":\"/profile/upload/2026/03/11/Apple AirPods Pro 3_20260311172154A009.png\",\"highlights\":\"降噪性能为AirPods Pro 2的2倍\\n内置心率传感器 健康监测\\n5种耳塞尺寸精准贴合\\n触控充电盒 滑动切歌\\nIP57防水防尘\"},{\"productId\":27,\"name\":\"索尼 WH-1000XM6 头戴式降噪耳机\",\"category\":\"耳机\",\"price\":3499.00,\"stock\":30,\"imageUrl\":\"/profile/upload/2026/03/11/索尼 WH-1000XM6 头戴式降噪耳机_20260311164651A002.png\",\"highlights\":\"全新QN3处理器 降噪性能飞跃\\n12麦克风阵列 极致降噪体验\\nLDAC高解析度无线传输\\nAI通话降噪 清晰人声\\n可折叠设计 便携出行\"},{\"productId\":28,\"name\":\"华为 FreeBuds 6i 真无线降噪耳机\",\"category\":\"耳机\",\"price\":349.00,\"stock\":100,\"imageUrl\":\"/profile/upload/2026/03/11/华为 FreeBuds 6i 真无线降噪耳机_20260311165046A003.png\",\"highlights\":\"27dB智慧动态降噪\\n千元级降噪效果 百元级价格\\n35小时超长总续航\\nIP54防水适合运动\\n华为音频分享\"},{\"productId\":29,\"name\":\"小米 Buds 5 Pro WiFi版 真无线耳机\",\"category\":\"耳机\",\"price\":1099.00,\"stock\":40,\"imageUrl\":\"/profile/upload/2026/03/11/小米 Buds 5 Pro WiFi版 真无线耳机_20260311165056A004.png\",\"highlights\":\"55dB超深度主动降噪\\nWiFi低延迟音频传输\\nLHDC 5.0高清音频编码\\n双单元声学架构 HiFi音质\\n空间音频沉浸体验\"},{\"productId\":30,\"name\":\"西圣 H1 Pro 头戴式蓝牙耳机\",\"category\":\"耳机\",\"price\":229.00,\"stock\":120,\"imageUrl\":\"/profile/upload/2026/03/11/西圣 H1 Pro 头戴式蓝牙耳机_20260311165105A005.png\",\"highlights\":\"60小时超长续航\\n蓝牙6.0芯片 稳定连接\\n双设备同时连接\\n百元价位降噪体验\\n可折叠便携设计\"}]}]', '2026-03-13 23:00:02', NULL);
