INSERT INTO `ai_chat_turn_audit` VALUES (78, 36, 100, '你好鸭', '你好呀！👋 我是小智，您的数码商城智能客服助手～\n\n很高兴为您服务！😊 我可以帮您：\n- 📱 推荐和查询手机、电脑、耳机等数码产品\n- 🛒 管理购物车和订单\n- 📦 查询物流和售后\n- 💬 处理各种购物问题\n\n有什么我可以帮您的吗？比如想找某类产品、查询订单，或者有其他购物问题？随时告诉我哦～ 😊', '[{\"title\": \"保修政策\", \"category\": \"POLICY\", \"knowledgeId\": \"2\"}, {\"title\": \"售后联系方式\", \"category\": \"FAQ\", \"knowledgeId\": \"8\"}, {\"title\": \"配送说明\", \"category\": \"POLICY\", \"knowledgeId\": \"3\"}]', NULL, 6497, 1, '2026-03-13 22:49:48');
INSERT INTO `ai_chat_turn_audit` VALUES (79, 36, 100, '你可以为我讲故事吗', '您好呀！😊 我是小智，数码商城的智能客服助手～\n\n我的主要专长是帮您处理数码购物相关的事情，比如：\n- 📱 推荐和查询手机、电脑、耳机等数码产品\n- 🛒 管理购物车和订单\n- 📦 查询物流和售后问题\n- 💬 解答各类购物疑问\n\n讲故事暂时不是我的强项呢～不过如果您想选购数码产品、查询订单状态，或者有任何购物问题，我都很乐意帮您！😄\n\n今天有什么可以帮您的吗？比如想找某类产品，或者查询订单？🛒', '[{\"title\": \"保修政策\", \"category\": \"POLICY\", \"knowledgeId\": \"2\"}, {\"title\": \"售后联系方式\", \"category\": \"FAQ\", \"knowledgeId\": \"8\"}, {\"title\": \"配送说明\", \"category\": \"POLICY\", \"knowledgeId\": \"3\"}]', NULL, 6931, 1, '2026-03-13 22:50:21');
INSERT INTO `ai_chat_turn_audit` VALUES (80, 24, 101, '有什么热门商品推荐？', '为您精选了各品类的热门商品，看看有没有您感兴趣的吧！😊\n\n## 📱 热门手机\n1. **苹果 iPhone 16 Pro Max 256GB** - ¥8,999 | A18 Pro芯片，4800万像素三摄，钛金属边框\n2. **华为 Mate 70 Pro 12+256GB** - ¥6,499 | 麒麟9020芯片，5700mAh大电池，鸿蒙5.0系统\n3. **小米15 Pro 12+256GB** - ¥4,599 | 骁龙8至尊版，6100mAh超大电池，徕卡影像\n4. **三星 Galaxy S25 Ultra 12+256GB** - ¥8,999 | 2亿像素四摄，内置S Pen，Galaxy AI助手\n5. **OPPO Find X8 Pro 16+256GB** - ¥5,299 | 天玑9400芯片，哈苏影像，5910mAh电池\n\n## 💻 热门笔记本电脑\n1. **MacBook Air 13英寸 M4 16+256GB** - ¥7,999 | M4芯片，18小时续航，仅1.24kg轻薄\n2. **华为 MateBook X Pro 酷睿Ultra 7 16+1TB** - ¥11,199 | 仅980g超轻，14.2英寸OLED屏\n3. **联想 ThinkPad X1 Carbon 2025 Ultra7 32+1TB** - ¥12,999 | 商务旗舰，2.8K OLED屏，军标认证\n\n## 🎧 热门耳机\n1. **Apple AirPods Pro 3** - ¥1,899 | 2倍降噪性能，心率监测，触控充电盒\n2. **索尼 WH-1000XM6 头戴式** - ¥3,499 | QN3处理器，12麦克风阵列，LDAC高解析\n3. **华为 FreeBuds 6i** - ¥349 | 27dB智慧降噪，35小时续航，性价比之选\n4. **小米 Buds 5 Pro WiFi版** - ¥1,099 | 55dB超深度降噪，WiFi低延迟，空间音频\n5. **西圣 H1 Pro 头戴式** - ¥229 | 60小时续航，蓝牙6.0，百元价位降噪\n\n您对哪款产品感兴趣呢？我可以帮您查看详细信息、对比参数，或者直接加入购物车哦！🛒', '[{\"title\": \"常见问题 - 如何查询订单\", \"category\": \"FAQ\", \"knowledgeId\": \"5\"}, {\"title\": \"配送说明\", \"category\": \"POLICY\", \"knowledgeId\": \"3\"}, {\"title\": \"售后联系方式\", \"category\": \"FAQ\", \"knowledgeId\": \"8\"}]', '[\"searchProducts\", \"searchProducts\", \"searchProducts\"]', 12598, 1, '2026-03-13 23:00:02');
INSERT INTO `ai_knowledge` VALUES (2, '保修政策', '保修政策说明：\n1. 所有商品享受国家三包政策\n2. 手机类产品：整机保修1年，电池保修6个月\n3. 电脑类产品：整机保修2年\n4. 配件类产品：保修1年\n5. 人为损坏不在保修范围内\n6. 保修期内免费维修，过保收取工本费', 'POLICY', 1, 'MANUAL', NULL, '2026-02-27 20:16:28', '2026-02-27 20:16:28', NULL);
INSERT INTO `ai_knowledge` VALUES (3, '配送说明', '配送信息：\n1. 下单后24小时内发货（节假日顺延）\n2. 默认顺丰快递，偏远地区使用圆通/中通\n3. 一线城市次日达，二三线城市2-3天\n4. 满99元免运费，不满99元收取10元运费\n5. 支持货到付款（仅限部分地区）\n6. 可在订单详情中查看物流信息', 'POLICY', 1, 'MANUAL', NULL, '2026-02-27 20:16:28', '2026-02-27 20:16:28', NULL);
INSERT INTO `ai_knowledge` VALUES (4, '支付方式', '支持以下支付方式：\n1. 微信支付\n2. 支付宝\n3. 银联在线支付\n4. 花呗分期（3/6/12期）\n5. 信用卡支付\n所有支付均通过加密通道，请放心使用。', 'FAQ', 1, 'MANUAL', NULL, '2026-02-27 20:16:28', '2026-02-27 20:16:28', NULL);
INSERT INTO `ai_knowledge` VALUES (5, '常见问题 - 如何查询订单', '查询订单方法：\n1. 在聊天中直接告诉我您的订单编号，我可以帮您查询\n2. 登录后进入\"我的订单\"页面查看\n3. 订单编号格式为 ORD 开头，如 ORD20250001\n4. 如需查询物流进度，也可以直接询问我', 'FAQ', 1, 'MANUAL', NULL, '2026-02-27 20:16:28', '2026-02-27 20:16:28', NULL);
INSERT INTO `ai_knowledge` VALUES (8, '售后联系方式', '售后服务联系方式：\n1. 在线客服：通过智能客服对话即可处理大部分售后问题\n2. 客服热线：400-888-8888（工作日 9:00-18:00）\n3. 邮箱：service@smartcs.com\n4. 微信公众号：SmartCS官方商城\n5. 工单系统：可通过对话让AI客服帮您创建售后工单', 'FAQ', 1, 'MANUAL', NULL, '2026-02-27 20:16:28', '2026-02-27 20:16:28', NULL);
